  how_3: 'हर दिन यह वह विषय चुनता है जिसकी परीक्षा पास है और जिसका सबसे ज़्यादा काम बाकी है (बचा काम ÷ बचे दिन)। एक दिन में 1–3 विषय, ब्लॉक में, ताकि आपको बार-बार विषय न बदलना पड़े।',
