  help_title: 'कैसे इस्तेमाल करें / कक्षा के लिए आइडिया',
  help_1: '“परीक्षाएँ और पाठ” खोलें: हर विषय, उसकी परीक्षा की तारीख और उसके पाठ डालें। हर पाठ को आसान/मध्यम/कठिन और कमज़ोर/ठीक-ठाक/मज़बूत चुनें।',
  help_2: '“पढ़ाई का समय” में हफ़्ते के हर दिन आप असल में कितने घंटे पढ़ सकते हैं, वह डालें और 25 या 50 मिनट के सेशन चुनें। फिर “मेरा प्लान बनाएँ” दबाएँ।',
  help_3: 'रोज़ “मेरा प्लान” खोलें और पूरे हुए सेशन पर टिक करें। कुछ छूट जाए तो “छूटे हुए दोबारा प्लान करें” दबाएँ, वे आने वाले दिनों में चले जाएँगे।',
  help_4: 'प्लान प्रिंट करके पढ़ाई की मेज़ के पास लगाएँ, या Google Calendar के लिए कैलेंडर फ़ाइल (.ics) डाउनलोड करें। आपका प्लान सिर्फ़ इसी डिवाइस पर सेव होता है।',
