  cap_short: 'এই সময় যথেষ্ট নয়। ঘণ্টা বাড়ান বা আগে শুরু করুন, না হলে প্ল্যানে প্র্যাকটিস পেপার আর অতিরিক্ত রিভিশন বাদ যাবে।',
