  tip_phone: 'अभ्यास करताना फोन दुसऱ्या खोलीत ठेवा किंवा “डू नॉट डिस्टर्ब” चालू करा. एक मेसेज 20 मिनिटांचे लक्ष मोडू शकतो.',
  tip_food: 'हलके, घरचे जेवण घ्या: वरण, पोळी, भात, दही, फळे, सुकामेवा. जास्त चहा, कॉफी, एनर्जी ड्रिंक किंवा जंक फूड अस्वस्थ करतात.',
  tip_move: 'दररोज 20–30 मिनिटे हालचाल करा: चालणे, सायकल, योग किंवा एखादा खेळ. त्याने मन ताजे राहते.',
  tip_test: 'स्वतःची चाचणी घ्या: पुस्तक बंद करून जे आठवते ते लिहा किंवा बोला. पुन्हा पुन्हा वाचण्यापेक्षा प्रश्न सोडवणे जास्त उपयोगी.',
  tip_bag: 'पेपरच्या आदल्या रात्री: प्रवेशपत्र, ओळखपत्र, पेन, पेन्सिल, कंपास पेटी आणि पाण्याची बाटली बॅगेत ठेवा. परीक्षा केंद्रावर लवकर पोहोचा.',
  tip_talk: 'ताण वाटतोय? आई-वडील, शिक्षक किंवा मित्राशी बोला. मोफत 24×7 हेल्पलाइन टेली-मानस: 14416 (अनेक भारतीय भाषांत).',
  how_title: 'नियोजक कसा काम करतो',
  how_1: 'प्रत्येक धड्याला वेळ तो किती कठीण आहे आणि तुम्हाला किती येतो यावरून मिळतो. कठीण आणि कच्च्या धड्याला, बऱ्यापैकी येणाऱ्या सोप्या धड्याच्या 3 पट वेळ मिळतो.',
  how_2: 'प्रत्येक विषयाचा क्रम: धडे शिकणे (कठीण आणि कच्चे आधी) → सर्व धड्यांची उजळणी 1 → सराव पेपर → परीक्षेआधीच्या हलक्या दिवशी अंतिम उजळणी.',
  how_3: 'दररोज तो असा विषय निवडतो ज्याची परीक्षा जवळ आहे आणि ज्याचे सर्वात जास्त काम बाकी आहे (बाकी काम ÷ बाकी दिवस). दिवसाला 1–3 विषय, गटांमध्ये, म्हणजे सारखा विषय बदलावा लागत नाही.',
  how_4: 'तो काम समान पसरवतो आणि शेवटी थोडा वेळ मोकळा ठेवतो. वेळ कमी असल्यास आधी सराव पेपर, मग जादा उजळणी वगळतो — आणि तुम्हाला सांगतो.',
  help_title: 'कसे वापरावे / वर्गासाठी कल्पना',
  help_1: '“परीक्षा आणि धडे” उघडा: प्रत्येक विषय, त्याची परीक्षेची तारीख आणि धडे भरा. प्रत्येक धड्यासाठी सोपा/मध्यम/कठीण आणि कच्चा/बरा/पक्का निवडा.',
  help_2: '“अभ्यासाची वेळ” मध्ये आठवड्याच्या प्रत्येक दिवशी तुम्ही खरोखर किती तास अभ्यास करू शकता ते भरा, आणि 25 किंवा 50 मिनिटांची सत्रे निवडा. मग “माझा प्लॅन बनवा” दाबा.',
  help_3: 'दररोज “माझा प्लॅन” उघडा आणि पूर्ण झालेल्या सत्रांवर टिक करा. काही चुकले तर “चुकलेली पुन्हा आखा” दाबा, ती पुढच्या दिवसांत जातील.',
  help_4: 'प्लॅन प्रिंट करून अभ्यासाच्या टेबलाजवळ लावा, किंवा Google Calendar साठी कॅलेंडर फाइल (.ics) डाउनलोड करा. तुमचा प्लॅन फक्त याच डिव्हाइसवर सेव्ह होतो.',
