  leave_help: 'ਬੋਰਡ ਇਮਤਿਹਾਨਾਂ ਤੋਂ ਪਹਿਲਾਂ ਕਈ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਸਟੱਡੀ ਲੀਵ ਮਿਲਦੀ ਹੈ। ਜੇ ਸਕੂਲ ਬੰਦ ਹੋ ਰਿਹਾ ਹੈ ਤਾਂ ਤਾਰੀਖ ਅਤੇ ਉਦੋਂ ਰੋਜ਼ ਦੇ ਪੜ੍ਹਾਈ ਦੇ ਘੰਟੇ ਚੁਣੋ। ਨਹੀਂ ਤਾਂ ਖਾਲੀ ਛੱਡੋ।',
