  leave_help: 'ବୋର୍ଡ ପରୀକ୍ଷା ପୂର୍ବରୁ ଅନେକ ଛାତ୍ରଛାତ୍ରୀ ପଢ଼ା ଛୁଟି ପାଆନ୍ତି। ସ୍କୁଲ୍ ବନ୍ଦ ହେଉଥିଲେ ତାରିଖ ଓ ସେତେବେଳେ ପ୍ରତିଦିନ କେତେ ଘଣ୍ଟା ପଢ଼ିବେ ବାଛନ୍ତୁ। ନହେଲେ ଖାଲି ଛାଡ଼ନ୍ତୁ।',
