  exams_help: 'ஒவ்வொரு பாடத்தையும் அதன் தேர்வுத் தேதி, தேர்வில் வரும் அத்தியாயங்களுடன் சேருங்கள். ஒவ்வொரு அத்தியாயமும் எவ்வளவு கடினம், உங்களுக்கு எவ்வளவு தெரியும் என்று தேர்ந்தெடுங்கள்: கடினமான, பலவீனமான அத்தியாயங்களுக்கு அதிக நேரம் கிடைக்கும்.',
