  paste_help: 'அத்தியாயப் பெயர்களைத் தட்டச்சு செய்யுங்கள் அல்லது ஒட்டுங்கள், ஒரு வரிக்கு ஒன்று.',
  chapters_added: '{n} அத்தியாயங்கள் சேர்க்கப்பட்டன.',
