  delete_chapter: 'அத்தியாயத்தை நீக்கு',
  confirm_delete_subject: '{name} மற்றும் அதன் எல்லா அத்தியாயங்களையும் நீக்கவா?',
  confirm_empty: 'எல்லாப் பாடங்களையும் திட்டத்தையும் நீக்கிவிட்டுப் புதிய வெற்றுத் திட்டத்தைத் தொடங்கவா?',
  no_chapters: 'இன்னும் அத்தியாயங்கள் இல்லை. இந்தத் தேர்வில் வரும் அத்தியாயங்களைச் சேருங்கள்.',
  no_subjects: 'இன்னும் பாடங்கள் இல்லை. “பாடம் சேர்” அழுத்துங்கள்.',
  no_date: 'இந்தப் பாடத்தின் தேர்வுத் தேதியைத் தேர்ந்தெடுங்கள்.',
  exam_before_start: 'இந்தத் தேர்வு தொடக்கத் தேதிக்கு முன் உள்ளது, எனவே திட்டத்தில் இல்லை.',
  exam_in: '{n} நாட்களில் தேர்வு',
