  leave_help: 'బోర్డు పరీక్షల ముందు చాలామందికి స్టడీ లీవ్ ఇస్తారు. స్కూల్ మూసేస్తే ఆ తేదీ, అప్పుడు రోజూ ఎన్ని గంటలు చదువుతారో ఎంచుకోండి. లేకపోతే ఖాళీగా వదిలేయండి.',
