  cap_short: 'ಇಷ್ಟು ಸಮಯ ಸಾಲದು. ಗಂಟೆಗಳನ್ನು ಹೆಚ್ಚಿಸಿ ಅಥವಾ ಬೇಗ ಆರಂಭಿಸಿ, ಇಲ್ಲದಿದ್ದರೆ ಯೋಜನೆಯಿಂದ ಅಭ್ಯಾಸ ಪತ್ರಿಕೆಗಳು ಮತ್ತು ಹೆಚ್ಚುವರಿ ಪುನರಾವರ್ತನೆ ಬಿಟ್ಟುಹೋಗುತ್ತವೆ.',
