  pomo_50: '50 മിനിറ്റ് + 10 മിനിറ്റ് ഇടവേള',
  pomo_help: 'ഇതാണ് പൊമൊഡോറോ രീതി: പൂർണ ശ്രദ്ധയോടെ പഠിക്കൂ, പിന്നെ ചെറിയ ഇടവേള എടുക്കൂ. ഏകദേശം 2 മണിക്കൂറിനു ശേഷം 15–30 മിനിറ്റ് നീണ്ട ഇടവേള എടുക്കൂ. ചെറിയ ക്ലാസുകളിലെ കുട്ടികൾ 25 മിനിറ്റ് തിരഞ്ഞെടുക്കൂ.',
